Matching Ayahs
- = Alif, Laam, Miim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Merekalah yang mendapat petunjuk dari Tuhan mereka, dan merekalah orang-orang yang beruntung. 2:5; 31:5
- = Wahai Bani Israil, ingatlah nikmat-Ku yang telah Aku berikan kepadamu dan bahwa Aku telah melebihkan kamu di atas seluruh umat (manusia). 2:47; 2:122
- = Itulah umat yang telah lalu. Baginya apa yang telah mereka usahakan dan bagimu apa yang telah kamu usahakan. Dan kamu tidak akan diminta pertanggungjawaban tentang apa yang telah mereka kerjakan. 2:134; 2:141
- = Kekal mereka di dalamnya. Siksa tidak akan diringankan dari mereka, dan mereka tidak diberi penangguhan. 2:162; 3:88
- = Kecuali orang-orang yang bertaubat setelah itu dan memperbaiki diri. Maka sungguh, Allah Maha Pengampun lagi Maha Penyayang. 3:89; 24:5
- = Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni Neraka. 5:10; 5:86
- = Dan tidak ada suatu tanda pun dari tanda-tanda (kekuasaan) Tuhan mereka yang datang kepada mereka, melainkan mereka selalu berpaling darinya. 6:4; 36:46
- = Dan sungguh, telah diperolok-olokkan beberapa rasul sebelum kamu, maka turunlah kepada orang-orang yang mencemoohkan di antara mereka, azab (balasan) olok-olokan yang mereka perolok-olokkan. 6:10; 21:41
- = Katakanlah: "Sungguh, aku takut akan azab hari yang besar jika aku mendurhakai Tuhanku." 6:15; 39:13
- = Maka gempa bumi menimpa mereka, dan mereka pun mati bergelimpangan di dalam rumah-rumah mereka. 7:78; 7:91
- = Lalu dia (Musa) melemparkan tongkatnya, maka tiba-tiba ia menjadi ular yang nyata. 7:107; 26:32
- = Dan dia mengeluarkan tangannya, maka tiba-tiba ia menjadi putih (bercahaya) bagi orang-orang yang melihatnya. 7:108; 26:33
- = Mereka berkata: "Kami telah beriman kepada Tuhan seluruh alam." 7:121; 26:47
- = Tuhan Musa dan Harun. 7:122; 26:48
- = Dan Aku akan memberi tangguh kepada mereka. Sungguh, rencana-Ku sangat kuat. 7:183; 68:45
- = Dialah yang mengutus Rasul-Nya dengan petunjuk dan agama yang benar, agar dimenangkan-Nya atas semua agama, walaupun orang-orang musyrik membencinya. 9:33; 61:9
- = Wahai Nabi, berjihadlah melawan orang-orang kafir dan orang-orang munafik, dan bersikap keraslah terhadap mereka. Tempat mereka adalah Neraka Jahanam, dan itulah seburuk-buruk tempat kembali. 9:73; 66:9
- = Dan mereka berkata: "Kapankah janji ini (akan terjadi), jika kamu orang-orang yang benar?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Dan sungguh, Kami telah mengutus Musa dengan bukti-bukti Kami dan dengan wewenang yang jelas. 11:96; 40:23
- = Dan sungguh, Kami telah memberikan Kitab (Taurat) kepada Musa, lalu diperselisihkan tentang Kitab itu. Dan sekiranya tidak ada ketetapan yang terdahulu dari Tuhanmu, niscaya telah diputuskan di antara mereka. Dan sungguh, mereka benar-benar dalam keraguan yang mendalam tentangnya. 11:110; 41:45
- = Itu tidak sulit bagi Allah. 14:20; 35:17
- = "Maka apabila Aku telah menyempurnakan kejadiannya, dan Aku telah meniupkan roh (ciptaan)-Ku ke dalamnya, maka tunduklah kamu kepadanya dengan bersujud." 15:29; 38:72
- = Maka para malaikat itu semuanya bersujud. 15:30; 38:73
- = (Allah) berfirman: "Maka keluarlah dari padanya, karena sesungguhnya kamu adalah orang yang terkutuk." 15:34; 38:77
- = (Iblis) berkata: "Ya Tuhanku, maka berilah aku penangguhan hingga hari (manusia) dibangkitkan." 15:36; 38:79
- = (Allah) berfirman: "Maka sesungguhnya kamu termasuk orang-orang yang diberi penangguhan." 15:37; 38:80
- = Hingga hari waktu yang telah ditentukan." 15:38; 38:81
- = Kecuali hamba-hamba-Mu yang terpilih di antara mereka. 15:40; 38:83
- = Sesungguhnya orang-orang yang bertakwa berada di dalam taman-taman (surga) dan mata air. 15:45; 51:15
- = (Ibrahim) berkata: "Apakah urusanmu yang penting, wahai para utusan?" 15:57; 51:31
- = Mereka menjawab: "Kami diutus kepada kaum yang berdosa." 15:58; 51:32
- = Orang-orang yang beriman dan tidak mencampuradukkan iman mereka dengan kezaliman, mereka itulah yang mendapat keamanan dan mereka itu adalah orang-orang yang mendapat petunjuk. 16:42; 29:59
- = Sehingga mereka mengingkari nikmat yang telah Kami berikan kepada mereka. Maka bersenang-senanglah kamu, kelak kamu akan mengetahui (akibatnya). 16:55; 30:34
- = Kemudian dia menempuh suatu jalan (yang lain). 18:89; 18:92
- = Pergilah kepada Fir'aun, sungguh dia telah melampaui batas. 20:24; 79:17
- = Dan orang-orang yang memelihara kemaluannya. 23:5; 70:29
- = Kecuali terhadap istri-istri mereka atau hamba sahaya yang mereka miliki, maka sesungguhnya mereka tidak tercela. 23:6; 70:30
- = Tetapi barangsiapa mencari di balik itu, maka mereka itulah orang-orang yang melampaui batas. 23:7; 70:31
- = Dan orang-orang yang memelihara amanat-amanat (yang dipikulnya) dan janjinya. 23:8; 70:32
- = (Nuh) berkata: "Ya Tuhanku, tolonglah aku karena mereka telah mendustakan aku." 23:26; 23:39
- = Tha, Sin, Mim. 26:1; 28:1
- = Inilah ayat-ayat Kitab yang jelas. 26:2; 28:2
- = Sesungguhnya pada yang demikian itu terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = Dan sesungguhnya Tuhanmu, Dialah Yang Maha Perkasa lagi Maha Penyayang. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = Dan Kami menenggelamkan golongan yang lain. 26:66; 37:82
- = Sesungguhnya aku adalah seorang rasul kepercayaan yang diutus kepadamu. 26:107; 26:125; 26:143; 26:162; 26:178
- = Maka bertakwalah kepada Allah dan taatilah aku. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = Dan aku tidak meminta upah kepadamu atas ajakan itu, upahku hanyalah dari Tuhan semesta alam. 26:109; 26:127; 26:145; 26:164; 26:180
- = Di dalam taman-taman dan mata air. 26:147; 44:52
- = Mereka berkata: "Sesungguhnya kamu adalah salah seorang dari orang-orang yang kena sihir." 26:153; 26:185
- = Kecuali istrinya – Kami telah menetapkan bahwa dia termasuk orang-orang yang tertinggal (bersama orang-orang yang diazab). 26:171; 37:135
- = Kemudian Kami binasakan golongan yang lain. 26:172; 37:136
- = Dan Kami hujani mereka dengan hujan (batu), maka betapa buruknya hujan bagi orang-orang yang telah diberi peringatan itu! 26:173; 27:58
- = Maka apakah mereka meminta supaya disegerakan azab Kami? 26:204; 37:176
- = (Yaitu) orang-orang yang melaksanakan salat dan menunaikan zakat, dan mereka yakin akan adanya akhirat. 27:3; 31:4
- = Dan (ingatlah) hari (ketika) Dia memanggil mereka, lalu Dia berfirman: "Di manakah sekutu-sekutu-Ku yang dahulu kamu klaim?" 28:62; 28:74
- = Dan (juga) nenek moyang kami yang terdahulu? 37:17; 56:48
- = Dan mereka saling mendekati, saling bertanya. 37:27; 52:25
- = Kecuali hamba-hamba Allah yang dibersihkan (dari dosa). 37:40; 37:74; 37:128; 37:160
- = Di dalam surga-surga yang penuh kenikmatan. 37:43; 56:12
- = Dan Kami abadikan untuknya (pujian yang baik) di kalangan orang-orang yang datang kemudian: 37:78; 37:108; 37:129
- = Sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik. 37:80; 37:121; 37:131; 77:44
- = Sesungguhnya dia termasuk hamba-hamba Kami yang beriman. 37:81; 37:111; 37:132
- = Ada apa dengan kamu? Bagaimana kamu mengambil keputusan? 37:154; 68:36
- = Al-Qur'an itu tidak lain hanyalah peringatan bagi seluruh alam. 38:87; 81:27
- = Kitab (Al-Qur'an) ini diturunkan dari Allah Yang Maha Perkasa lagi Maha Bijaksana. 39:1; 45:2; 46:2
- = Ha, Mim. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = Demi Kitab yang jelas. 43:2; 44:2
- = Maka biarkanlah mereka tenggelam (dalam kebathilan) dan bermain-main, sampai mereka menjumpai hari yang diancamkan kepada mereka. 43:83; 70:42
- = (Kepada mereka dikatakan): "Makan dan minumlah dengan nikmat karena amal baik yang telah kamu kerjakan." 52:19; 77:43
- = Ataukah kamu meminta upah kepada mereka, sehingga mereka dibebani dengan utang? 52:40; 68:46
- = Ataukah ada pada mereka ilmu tentang yang gaib, lalu mereka menuliskannya? 52:41; 68:47
- = Maka betapa dahsyatnya azab-Ku dan peringatan-Ku! 54:16; 54:21; 54:30
- = Dan sungguh, telah Kami mudahkan Al-Qur'an untuk pelajaran, maka adakah orang yang mau mengambil pelajaran? 54:17; 54:22; 54:32; 54:40
- = Maka nikmat Tuhanmu yang manakah yang kamu dustakan? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = Segolongan besar dari orang-orang yang terdahulu. 56:13; 56:39
- = Bahkan kami menjadi orang-orang yang kehilangan (hasil panen kami)? 56:67; 68:27
- = Maka bertasbihlah dengan (menyebut) nama Tuhanmu Yang Mahabesar. 56:74; 56:96; 69:52
- = (Al-Qur'an) adalah wahyu yang diturunkan dari Tuhan seluruh alam. 56:80; 69:43
- = Apa yang di langit dan apa yang di bumi senantiasa bertasbih kepada Allah, dan Dialah Yang Maha Perkasa lagi Maha Bijaksana. 59:1; 61:1
- = Apabila dibacakan kepadanya ayat-ayat Kami, dia berkata: "Dongeng-dongeng orang dahulu." 68:15; 83:13
- = Maka dia berada dalam kehidupan yang menyenangkan. 69:21; 101:7
- = Di dalam surga yang tinggi. 69:22; 88:10
- = Dan dia tidak menganjurkan memberi makan orang miskin. 69:34; 107:3
- = Sesungguhnya (Al-Qur'an) itu adalah firman (Allah) yang disampaikan oleh seorang rasul yang mulia (Jibril). 69:40; 81:19
