- Dan barangsiapa taat kepada Allah dan Rasul-Nya, Allah akan memasukkannya ke dalam surga-surga yang mengalir di bawahnya sungai-sungai. (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- Sesungguhnya Dia hanya mengharamkan bagimu bangkai, darah, daging babi, dan apa yang disembelih dengan menyebut nama selain Allah. (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- Bahwa janganlah kamu menyembah selain Allah; sesungguhnya aku takut kamu akan azab hari yang besar. (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- Itu adalah sebagian dari berita-berita gaib yang Kami wahyukan kepadamu; engkau tidak berada di sisi mereka ketika mereka memutuskan. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- Apakah kamu merasa heran bahwa peringatan datang kepadamu dari Tuhanmu melalui seorang laki-laki di antara kamu, untuk memberi peringatan kepadamu? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- Katakanlah: "Sesungguhnya aku dilarang menyembah tuhan-tuhan yang kamu seru selain Allah." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- Kecuali terhadap istri-istri mereka atau budak-budak yang mereka miliki, maka sesungguhnya mereka tidak tercela. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- Karena Allah memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- Api, lalu dia berkata kepada keluarganya: "Tinggallah kamu, sesungguhnya aku melihat api, mudah-mudahan aku dapat membawa sesuatu kepadamu daripadanya." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- Dia berkata: "Aku lebih baik daripadanya; Engkau ciptakan aku dari api, dan dia Engkau ciptakan dari tanah." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- Dan apabila dikatakan kepada mereka: "Marilah kamu kepada apa yang diturunkan Allah dan kepada Rasul." (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- Dan janganlah kamu bersedih hati terhadap mereka, dan janganlah kamu bersempit dada terhadap tipu daya mereka. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- Dan jika Allah menimpakan suatu bahaya kepadamu, maka tidak ada yang dapat menghilangkannya selain Dia, dan jika. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- Sebelum mereka umat-umat yang telah lalu, mereka berjalan di tempat-tempat kediaman mereka; sesungguhnya pada yang demikian itu terdapat tanda-tanda. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- Dan Kami jadikan penutup di atas hati mereka, agar mereka tidak memahaminya, dan di telinga mereka sumbatan, dan jika. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- Rasul-rasul mereka datang dengan bukti-bukti yang nyata, tetapi Allah tidaklah akan menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- Dan di bumi, dan tidak ada bagimu selain Allah seorang pelindung dan tidak pula seorang penolong. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- Kemudian kamu akan dikembalikan kepada (Allah) yang mengetahui yang gaib dan yang nyata, lalu Dia memberitakan kepadamu apa yang telah kamu kerjakan. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- Malam agar kamu beristirahat padanya, dan siang agar kamu melihat; sesungguhnya pada yang demikian itu terdapat tanda-tanda bagi kaum yang berpikir. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- Dan apa yang diturunkan kepadamu dari Tuhanmu, pasti akan menambah kesombongan dan kekafiran bagi kebanyakan mereka. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- Dia berkata: "Wahai kaumku! Bagaimana pendapatmu jika aku berada di atas bukti yang nyata dari Tuhanku dan Dia memberiku." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- Dan mereka berkata: "Mengapa tidak diturunkan kepadanya suatu mukjizat dari Tuhannya?" Katakanlah: "Sesungguhnya." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- Sebelum datang hari yang tidak dapat ditolak kedatangannya dari Allah. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- Itulah karunia Allah, yang diberikan-Nya kepada siapa yang Dia kehendaki, dan Allah mempunyai karunia yang besar. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- Dan sesungguhnya pada binatang-binatang ternak itu terdapat pelajaran bagimu; Kami memberimu minum dari apa yang ada dalam perutnya. (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- Bahwa itu adalah kebenaran dari Tuhan mereka, dan Allah tidak lengah terhadap apa yang mereka kerjakan. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- Dari depan mereka dan dari belakang mereka, agar kamu tidak menyembah selain Allah. (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- Sesungguhnya kamu mendatangi laki-laki dengan syahwat (nafsu) meninggalkan wanita, bahkan kamu adalah kaum yang melampaui batas. (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- Kekal di dalamnya, selama langit dan bumi masih ada, kecuali jika Tuhanmu menghendaki (yang lain). (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- Siapa yang di langit dan siapa yang di bumi, kecuali siapa yang dikehendaki Allah. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- Di dalamnya mereka dipakaikan gelang dari emas dan mutiara, dan pakaian mereka di dalamnya adalah sutera. (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
- Dan Dia menurunkan air dari langit, lalu dengan air itu Dia mengeluarkan buah-buahan sebagai rezeki untukmu. (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ) 2:22; 14:32
- Dan (ingatlah) ketika Kami mengambil janjimu dan Kami angkat gunung (Thursina) di atasmu: "Peganglah dengan kuat apa yang Kami berikan kepadamu." (وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ) 2:63; 2:93
- Maka dia berpaling dari mereka dan berkata: "Wahai kaumku! Sungguh aku telah menyampaikan kepadamu risalah Tuhanku dan aku telah memberi nasihat kepadamu." (فَتَوَلَّى عَنْهُمْ وَقَالَ يَاقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْتُ لَكُمْ) 7:79; 7:93
- Sungai-sungai mengalir di bawah mereka, mereka dipakaikan gelang dari emas di dalamnya. (تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ) 18:31; 22:23
- Sekiranya mereka memiliki semua apa yang ada di bumi dan sebanyak itu lagi, untuk menebus diri mereka. (لَوْ أَنَّ لَهُم مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا) 5:36; 13:18
- Tidak ada suatu binatang melata pun, tetapi Dia menangguhkan mereka sampai waktu yang ditentukan, dan apabila ajal mereka tiba. (مِن دَابَّةٍ وَلَكِن يُؤَخِّرُهُمْ إِلَى أَجَلٍ مُّسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ) 16:61; 35:45
- Kami telah menciptakan kamu dari tanah, kemudian dari setetes mani, kemudian dari segumpal darah, kemudian. (خَلَقْنَاكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ) 22:5; 40:67
- Maka Allah akan memberi keputusan di antara mereka pada hari Kiamat tentang apa yang mereka perselisihkan. (فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 22:69
- Telah datang kepadamu ilmu, tidak ada bagimu dari Allah seorang pelindung dan tidak. (جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا) 2:120; 13:37
- Dan apabila Kami memberikan nikmat kepada manusia, dia berpaling dan menjauh, dan apabila dia ditimpa kesusahan. (وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ وَنَأَى بِجَانِبِهِ وَإِذَا مَسَّهُ الشَّرُّ) 17:83; 41:51
- Dan tidak ada sesuatu yang lebih kecil dan tidak pula yang lebih besar dari itu, melainkan tercatat dalam Kitab yang jelas (Lauh Mahfuz). (وَلَا أَصْغَرَ مِن ذَلِكَ وَلَا أَكْبَرَ إِلَّا فِي كِتَابٍ مُّبِينٍ) 10:61; 34:3

